def pushes(xs):
    """Push each value of xs into an empty list with your push."""
    h = []
    for x in xs:
        push(h, x)
    return h

def drain(h):
    """Pop everything with your pop."""
    out = []
    while h:
        out.append(pop(h))
    return out

def is_heap(h):
    return all(h[(i - 1) // 2] <= h[i] for i in range(1, len(h)))

